script:
today = frappe.utils.nowdate()

# =====================================
# AMC STATUS
# =====================================

if doc.custom_amc_end_date:

    days = frappe.utils.date_diff(doc.custom_amc_end_date, today)

    if days < 0:
        doc.custom_amc_status = "Expired"

    elif days <= 60:
        doc.custom_amc_status = "Expiring Soon"

    else:
        doc.custom_amc_status = "Active"

else:
    doc.custom_amc_status = "No AMC"

# =====================================
# WARRANTY STATUS
# =====================================

if doc.custom_warranty_end_date:

    days = frappe.utils.date_diff(doc.custom_warranty_end_date, today)

    if days < 0:
        doc.custom_warranty_status = "Expired"

    elif days <= 60:
        doc.custom_warranty_status = "Expiring Soon"

    else:
        doc.custom_warranty_status = "Active"

else:
    doc.custom_warranty_status = "No Warranty"
